    }
    if (F.prune) {
      const xa = xOfAge(u - F.prune.from), xc = xOfAge(u - F.prune.to);
      wal += `<g opacity="${(1 - ease(F.prune.f)).toFixed(2)}">${tape(xa, xc, false)}</g>`;
    }
    const ticks = [];
    let last = -Infinity;
    for (let n = 1; n < 24 * 8; n++) {
      const x = xOfAge((u % (1 / 24)) + (n - 1) / 24);
      if (x < xb + 0.5) break;
      if (Math.abs(x - last) < 1.3) continue;
      ticks.push(k.lineOnTop([x, WAL_Y - 1.8], [x, WAL_Y + 1.8], z + 1.2, P));
      last = x;
    }
    wal += L(ticks.join(""), { tone: "lo" });
    const pins = kept.map((j) => xOfAge(u - list[j])).filter((x) => x >= xb - 0.1);
    for (const x of pins) wal += slab({ x: x - 0.6, y: WAL_Y + 2.4, w: 1.2, d: 1.2, r: 0.3 }, z, 2.6, { tone: "mid", crease: "lo" });
    // WAL segments leaving the primary for the store, as in Fig 6, every second or so, and
    // the replica fetching each one moments after it lands
    // In an outage each upload climbs, fails and falls back to retry; after it, the backlog
    // goes up at four times the pace and the replica downloads as fast.
    const down = out && u >= out.from && u < out.to;
    const catching = out && u >= out.to && u < out.to + out.catchUp;
    const period = catching ? WAL.period / 4 : WAL.period;
    const n1 = Math.floor(u / period);
    const end = [Math.min(X_NOW - 2, xTo), WAL_Y, z + 1.2];
    for (let s0 = n1; s0 > n1 - 8; s0--) {
      const t0 = s0 * period;
      const f = (u - t0) / WAL.up;
      if (f >= 0 && f < 1) {
        if (down) {
          const [x, y] = parts.PORT(0);
          const h = f < 0.5 ? f * 2 : 2 - f * 2; // up towards the store, and back
          flying += parts.chipSvg([x, y, parts.PORT(0)[2] + 22 * h], false);
        } else flying += parts.chipSvg(parts.flight(parts.PORT(0), end, f), false);
      }
      const g = (u - t0 - WAL.up - WAL.wait[1]) / WAL.down;
      if (!down && g >= 0 && g < 1) flying += parts.chipSvg(parts.flight(end, parts.PORT(1), g), false);
    }

    // words at the end of the trays and of the tape
    const day = (t) => nameOf(GRAIN, t + 1e-6).slice(5) + (Math.abs(t - Math.round(t)) < 1e-6 ? " 00:00" : "");
    const W = [];
    const tag = (pos, s, sub = false) => { const r = rowAt(pos); W.push(parts.label([STAND.x + STAND.w, r.y, r.z], s, { anchor: "start", dx: 6, dy: 3, sub })); };
    if (running !== null) tag(0, `BACKUP ${day(list[latest])} · RUNNING`);
    if (running !== null) { const r = rowAt(0); W.push(parts.label([STAND.x + STAND.w, r.y, r.z], "uploads only what changed", { anchor: "start", dx: 6, dy: 13, sub: true })); }
    else if (kept.length) {
      const s0 = backupStats(kept[0], list, ps);
      tag(0, `NEWEST · ${day(list[kept[0]])}`);
      { const r = rowAt(0); W.push(parts.label([STAND.x + STAND.w, r.y, r.z], `${s0.up} uploaded, ${s0.ref} referenced`, { anchor: "start", dx: 6, dy: 13, sub: true })); }
    }
    if (kept.length > 1) tag(posOf(oldest), `OLDEST KEPT · ${day(list[oldest])}`);
    tag(BACK, "OLDER OBJECTS · still referenced", true);
    W.push(parts.label([X_NOW + 8, WAL_Y, z], "WAL SEGMENTS", { anchor: "start", dx: 4, dy: -4 }));
    W.push(parts.label([X_NOW + 8, WAL_Y, z], `back to ${day(F.boundary)}`, { anchor: "start", dx: 4, dy: 6, sub: true }));
    return { F, rows, tiles, flying, wal, labels: W.join(""), stats: (j) => backupStats(j, list, ps) };
  }
  // the legend draws the same parts
  return Object.assign(render, { tileSvg, traySvg, standSvg });
}

// One line for the readout. clock(t) names a moment. A backup takes minutes; the figure
// draws it slowed, so the readout names the moment it ran rather than the running clock.
function storyOf(u, keep, manual, hovered, clock) {
  const F = frameOf(u, keep, manual);
  const { list, kept, running, latest } = F;
  const ps = partitionsAt(GRAIN, u);
  const day = (t) => nameOf(GRAIN, t + 1e-6) + (Math.abs(t - Math.round(t)) < 1e-6 ? " 00:00" : "");
  const plural = (n, s) => `${n} ${s}${n === 1 ? "" : "s"}`;
  if (hovered?.row !== undefined) {
    const j = list.findIndex((t) => Math.abs(t - hovered.row) < 1e-6);
    if (j >= 0) {
      const s = backupStats(j, list, ps);
      return `Backup ${day(list[j])} · ${plural(s.up, "partition")} uploaded, ${s.ref} referenced in ${plural(s.prefixes - 1, "older backup")} · restore it, then replay WAL to any moment since`;
    }
  }
  if (hovered?.p !== undefined && ps.includes(hovered.p) && kept.length) {
    const p = hovered.p;
    const h = holderOf(p, kept[0], list);
    const s = stateOf(p, u);
    if (h < 0 || !s) return `${nameOf(GRAIN, p)} · active · in no backup yet, only in the WAL`;
    const where = kept.includes(h) ? `the backup of ${day(list[h])}` : `an older backup, ${day(list[h])}, kept while referenced`;
    const form = stateOf(p, list[h]).form;
    return `${nameOf(GRAIN, p)} · held as ${form === "cold" ? "_pm and index only, data in cold storage" : form} by ${where} · every later backup points at it`;
  }
  if (running !== null) {
    const s = backupStats(latest, list, ps);
    return `${clock(list[latest])} · BACKUP DATABASE · checkpoint, diff against the last manifest, upload ${plural(s.up, "changed partition")}`;
  }
  if (F.swept) return `${clock(list[F.done])} · keeping the latest ${keep} · retention sweeps the backup of ${day(list[F.swept.j])} and every object no kept manifest references`;
  if (F.prune) return `${clock(list[F.done] + CLEANER)} · the WAL cleaner deletes WAL up to the oldest kept backup, ${day(F.prune.to)}`;
  const next = Math.floor(u) + 1 - u;
  return `${clock(u)} · next backup in ${Math.ceil(next * 24)}h · WAL kept back to ${day(F.boundary)}, the oldest of ${keep} backups`;
}

// The model behind Fig 9: the object store becomes unreachable for three days, then
// recovers. Pure: everything is a function of u (days, PARTITION BY DAY, as in Fig 2).
//
// From the Enterprise code (checked 2026-10-22; nothing treats an outage as a state of its
// own, each part retries on its own, and nothing local depends on the store):
//   - The primary keeps ingesting and applying WAL. Its uploader retries every 200 ms,
//     forever; each segment keeps an upload.pending marker, so local WAL purge keeps it.
//     Nothing caps that growth: it lasts until the store is back, or the disk is full.
//   - The replica polls every second, fails, keeps serving the data it has, and falls behind.
//   - A durable-ACK client gets no durable acks: no error either, its store-and-forward
//     buffer just grows. When the buffer is full (sf_max_total_bytes, 10 GiB on disk by
//     default) an append blocks 30 s, then throws. Plain-ACK clients are not affected.
//   - TO REMOTE cannot upload: the partition stays local, retried on every policy sweep.
//   - DROP LOCAL still seals the partition, a WAL event, so it turns read-only; but its local
//     data is never dropped without a durable remote copy, so it stays local and served.
//   - A query on a partition already served from cold storage fails, "cold-storage download
//     failed"; queries on local partitions are unaffected.
//   - Each nightly backup fails and is recorded as failed in backups(); nothing retries it
//     until the next schedule. The WAL cleaner finds no new backup and deletes nothing.
// On recovery the backlog goes up in txn order, the replica catches up, the client gets one
// cumulative durable ack and trims, pending partitions upload, and seals complete.





const W0 = 60 + 20 / 24; // 2026-10-21 20:00, the store becomes unreachable
const W1 = W0 + 3; // three days later it is back
const CATCH_UP = 0.4; // the backlog worked off, as drawn
const U_START = 60.3;
const U_END = W1 + 1.3;
const FAILED = [61, 62, 63]; // the nightly backups that fail
// the cluster from Fig 10, with no instance able to do manager work while the store is down
const C7 = {
  lanes: [0, 1],
  manager: 0,
  schedule: { name: "outage", period: 1e6, segments: [
    { from: 0, to: W0, manager: 0, down: -1 },
    { from: W0, to: W1, manager: -1, down: -1 },
    { from: W1, to: 1e6, manager: 0, down: -1 },
  ] },
};
// the durable-ACK client's buffer, for an example ingest of 4 MB a minute
const SF_CAP_GIB = 10;
const INGEST_MB_MIN = 4;
const GIB_PER_DAY = (INGEST_MB_MIN * 60 * 24) / 1024;

const phaseOf = (u) => (u < W0 ? "before" : u < W1 ? "outage" : u < W1 + CATCH_UP ? "catchup" : "after");

// What the client has buffered, in GiB: it grows until the store is back, capped, and the
// cumulative durable ack after recovery trims it in one go.
function bufferOf(u) {
  const base = 0.02;
  if (u < W0) return base;
  const grown = Math.min(SF_CAP_GIB, base + (Math.min(u, W1) - W0) * GIB_PER_DAY);
  if (u < W1) return grown;
  const f = Math.min(1, (u - W1) / (CATCH_UP * 0.6));
  return grown + (base - grown) * f;
}
const fullAt = W0 + (SF_CAP_GIB - 0.02) / GIB_PER_DAY; // when the buffer fills

// How far behind the store the replica is, in days.
function lagOf(u) {
  if (u < W0) return 0;
  if (u < W1) return u - W0;
  const f = Math.min(1, (u - W1) / CATCH_UP);
  return (W1 - W0) * (1 - f);
}

// Local WAL the primary holds because it could not upload it, in days of writes.
function backlogOf(u) {
  if (u < W0) return 0;
  if (u < W1) return u - W0;
  return Math.max(0, (W1 - W0) * (1 - (u - W1) / CATCH_UP));
}

// Partitions waiting on the store at u: due TO REMOTE but not uploaded, and past DROP LOCAL
// (sealed) but still local.
function waitingOf(u, partitions, eventsOf) {
  let upload = 0, local = 0;
  for (const p of partitions) {
    const e = eventsOf(GRAIN, p, C7);
    if (u > p + 1 + ttlOf(GRAIN, 0, p) + 0.005 && u < e.up) upload++;
    if (u >= e.seal && u < e.cold[0]) local++;
  }
  return { upload, local };
}


// Fig 9's moving parts at time u: Fig 10's cluster (primary, replica, object store with the
// WAL tape, backup stand) through an object store outage, plus a durable-ACK client at the
// end of the feed with its store-and-forward buffer as a gauge.






// the client past the end of the feed, drawn as Fig 8's: a box on feet with its
// store-and-forward ring on top, one cell lit per share of the buffer in use
const CLIENT7 = { x: FEED.x1 + 8, y: FEED.y - 9, w: 30, d: 18, h: 12 };
const CELLS = 60; // two rows of 30, as in Fig 8
const PORT7 = [CLIENT7.x, CLIENT7.y + CLIENT7.d / 2, 9];

function makeOutage(k, P, parts, scene, backups) {
  const S = (paths, style) => k.solidSvg(paths, style);
  const L = (d, style) => k.lineSvg(d, style);
  const D = (pts, style) => k.dotsSvg(pts, style);
  const at = (pt) => k.iso(pt, P);
  const slab = (plan, z, h, style) => S(k.slabOf(plan, z, h, P, 2, Math.min(0.3, h / 3)), style);

  // the client, static, as Fig 8 draws it: feet, the case with its seam, the ring's panel
  // and the port facing the feed
  function clientSvg() {
    const { x, y, w, d, h } = CLIENT7;
    let out = "";
    for (const [fx, fy] of [[x + 3, y + 3], [x + w - 3, y + 3], [x + 3, y + d - 3], [x + w - 3, y + d - 3]]) out += S(k.cylinder(fx, fy, 1.6, -10, 10, P, 18), { tone: "mid" });
    out += S(k.slabOf({ x, y, w, d, r: 1.5 }, 0, h, P, 3, 0.6), { tone: "mid", inner: L(k.sideSeam({ x, y, w, d, r: 1.5 }, 3.5, P, 3), { tone: "faint" }) });
    out += slab({ x: x + 1.5, y: y + 2, w: w - 3, d: d - 4, r: 0.6 }, h, 0.8, { tone: "lo", crease: "none" });
    out += S(k.cylinder(PORT7[0], PORT7[1], 1.5, 7.5, 3, P, 18), { tone: "mid" });
    return out;
  }
  // the ring: a lit cell per sixtieth of the buffer in use, as Fig 8 lights unacknowledged frames
  function gaugeSvg(gib) {
    const { x, y, d, h } = CLIENT7;
    const n = Math.round(Math.min(1, gib / SF_CAP_GIB) * CELLS);
    let out = "";
    for (let c = 0; c < n; c++) {
      const row = Math.floor(c / 30), col = c % 30;
      out += slab({ x: x + 1.9 + col * 0.88, y: y + 3 + (row * (d - 6)) / 2, w: 0.72, d: (d - 6) / 2 - 0.4, r: 0.12 }, h + 0.8, 1.4, { tone: "lit", crease: "lo", lit: true });
    }
    return out;
  }
  // WAL the primary keeps because it could not upload it: a stack of segments by its port
  function pileSvg(days) {
    const n = Math.min(14, Math.round(days * 4.5));
    const [px, py] = parts.PORT(0);
    let out = "";
    for (let j = 0; j < n; j++) {
      const col = j % 2, row = Math.floor(j / 2);
      out += parts.chipSvg([px - 7 - col * 4.2, py + 4, HEAD.h + 0.6 + row * 1.7], j >= n - 2);
    }
    return out;
  }

  const span = (days) => {
    const h = Math.round(days * 24);
    return h < 24 ? `${h}h` : `${Math.floor(h / 24)}d ${h % 24}h`;
  };

  function render(u, t) {
    const phase = phaseOf(u);
    const ps = partitionsAt(GRAIN, u);
    const f = scene(GRAIN, u, null, C7);
    const b = backups(u, 5, [], null, { failed: FAILED, outage: { from: W0, to: W1, catchUp: CATCH_UP } });
    const gib = bufferOf(u);
    const wait = waitingOf(u, ps, eventsOf);
    const down = phase === "outage";

    // the words
    const W = [];
    const beside = (i) => [HEAD.x + HEAD.w, LANE_Y[i] - HEAD.d / 2, HEAD.h];
    const under = (i) => [HEAD.x + HEAD.w, LANE_Y[i] + HEAD.d / 2, 4];
    W.push(parts.label(beside(0), "PRIMARY", { anchor: "start", dx: 8, dy: -6 }));
    W.push(parts.label(beside(0), down ? `keeps ingesting · ${span(backlogOf(u))} of WAL kept locally` : phase === "catchup" ? "uploading the backlog" : "uploads its WAL every second", { anchor: "start", dx: 8, dy: 4, sub: true }));
    W.push(parts.label(under(1), "REPLICA", { anchor: "start", dx: -6, dy: 12 }));
    W.push(parts.label(under(1), lagOf(u) > 0.01 ? `behind by ${span(lagOf(u))} · still serving its data` : "applies the WAL from the object store", { anchor: "start", dx: -6, dy: 22, sub: true }));
    const cl = [CLIENT7.x + CLIENT7.w, CLIENT7.y + CLIENT7.d / 2, CLIENT7.h];
    W.push(parts.label(cl, "CLIENT · DURABLE ACK", { anchor: "start", dx: 8, dy: 2 }));
    const full = down && u >= fullAt;
    W.push(parts.label(cl, full ? "FULL · appends block, then throw" : `${gib.toFixed(gib < 1 ? 2 : 1)} of ${SF_CAP_GIB} GiB unacknowledged`, { anchor: "start", dx: 8, dy: 13, sub: !full }));
    const deckAt = [(DECK.x + X_NOW) / 2, STORE6.y + STORE6.d, STORE6.z];
    if (down) {
      W.push(parts.label(deckAt, "OBJECT STORE UNREACHABLE", { dy: 13 }));
      W.push(parts.label(deckAt, `for ${span(u - W0)} · every part retries on its own`, { dy: 24, sub: true }));
    }
    let row = down ? 35 : 13;
    if (wait.upload || wait.local) {
      const bits = [];
      if (wait.upload) bits.push(`${wait.upload} waiting for TO REMOTE`);
      if (wait.local) bits.push(`${wait.local} past DROP LOCAL kept local`);
      W.push(parts.label(deckAt, bits.join(" · "), { dy: row, sub: true }));
      row += 11;
    }
    const failedSince = FAILED.filter((x) => x <= u).length;
    if (failedSince && u < 64 + 0.2) W.push(parts.label(deckAt, `${failedSince} nightly backup${failedSince === 1 ? "" : "s"} failed · none retried until the next run`, { dy: row, sub: true }));

    return { f, b, gauge: gaugeSvg(gib), pile: pileSvg(backlogOf(u)), labels: W.join(""), remote: down ? 0.45 : 1, phase, wait, gib, full };
  }
  return Object.assign(render, { clientSvg });
}

// One line for the readout.
function storyOf7(u, t, clock) {
  const phase = phaseOf(u);
  const ps = partitionsAt(GRAIN, u);
  const wait = waitingOf(u, ps, eventsOf);
  if (phase === "before") return `${clock} · all well · the store goes down at 20:00`;
  if (phase === "outage") {
    const lines = [
      "ingest and local queries carry on; the primary keeps every WAL segment it could not upload, with no cap but the disk",
      "the replica polls every second, fails, and keeps serving what it has",
      "durable-ACK clients get no acks and keep buffering; plain-ACK clients are unaffected",
      `TO REMOTE waits${wait.upload ? ` (${wait.upload})` : ""}; DROP LOCAL seals but keeps the data local${wait.local ? ` (${wait.local})` : ""}`,
      "a query on a partition served from cold storage fails: cold-storage download failed",
      "the nightly backup fails and is recorded as failed; the WAL cleaner deletes nothing",
    ];
    return `${clock} · store unreachable · ${lines[Math.floor(t / 3) % lines.length]}`;
  }
  if (phase === "catchup") return `${clock} · store back · the backlog goes up in txn order, the replica catches up, the client is trimmed by one cumulative durable ack`;
  return `${clock} · caught up · pending partitions uploaded, seals completed; the next backup runs at midnight`;
}

// Live behaviour of Fig 9: three days of object store outage and the recovery after it,
// played at Fig 2's pace (a day every UNIT_SECONDS) and looped. Space pauses.
// `stage` is the .iso-stage element, `data` = { P }, `k` the iso kit, `G` the lathe kit.







const SVG_NS = "http://www.w3.org/2000/svg";
const FADE = 0.25; // days of fade at each end of the loop

function mount(stage, data, k, G) {
  const { P } = data;
  const parts = makeParts(k, G, P);
  const draw = makeOutage(k, P, parts, makeScene(k, P, parts), makeBackups(k, P, parts));
  const svg = stage.querySelector("svg");
  const figure = stage.closest(".iso-figure");
  const one = (name) => svg.querySelector(`[data-part="${name}"]`);
  const layers = {
    store: one("store"), copy: one("copy"), feed: one("feed"), hand: one("hand"), blocks: [one("blocks-0"), one("blocks-1")], lamps: [one("lamp-0"), one("lamp-1")],
    wal: one("wal6"), rows: one("rows6"), tiles: one("tiles6"), flying: one("flying6"), labels6: one("labels6"),
    remote: one("remote"), gauge: one("gauge"), pile: one("pile"), labels: one("labels7"), all: one("moving7"),
  };
  const readout = figure?.querySelector("[data-readout]");
  const still = matchMedia("(prefers-reduced-motion: reduce)");

  let u = data.u0 ?? U_START, t = 0;
  let paused = false, frame = 0, last = 0, visible = false;
  const written = new Map();
  const put = (el, html) => { if (el && written.get(el) !== html) { el.innerHTML = html; written.set(el, html); } };
  function sync(layer, items) {
    if (!layer) return;
    const seen = new Set();
    let prev = null;
    for (const it of items) {
      seen.add(it.id);
      let el = layer.querySelector(`:scope > [data-id="${it.id}"]`);
      if (!el) { el = document.createElementNS(SVG_NS, "g"); el.dataset.id = it.id; if (it.p !== undefined) el.dataset.p = String(it.p); }
      const next = prev ? prev.nextSibling : layer.firstChild;
      if (next !== el) layer.insertBefore(el, next);
      el.setAttribute("transform", k.translateAlong(P, [it.x, it.y, it.z ?? 0]));
      const op = it.opacity ?? 1;
      if (op < 0.999) el.setAttribute("opacity", op.toFixed(2)); else el.removeAttribute("opacity");
      if (el.dataset.key !== it.key) { el.innerHTML = it.html(); el.dataset.key = it.key; }
      prev = el;
    }
    for (const el of [...layer.children]) if (!seen.has(el.dataset.id)) el.remove();
  }

  function render() {
    const r = draw(u, t);
    [0, 1].forEach((i) => sync(layers.blocks[i], r.f.lanes[i]));
    sync(layers.store, r.f.store);
    put(layers.copy, r.f.copy);
    put(layers.feed, r.f.feed);
    r.f.lamps.forEach((lamp, i) => put(layers.lamps[i], lamp));
    layers.hand?.setAttribute("d", r.f.hand);
    sync(layers.rows, r.b.rows);
    sync(layers.tiles, r.b.tiles);
    put(layers.wal, r.b.wal);
    put(layers.flying, r.b.flying);
    put(layers.labels6, r.b.labels);
    put(layers.gauge, r.gauge);
    put(layers.pile, r.pile);
    put(layers.labels, r.labels);
    layers.remote?.setAttribute("opacity", r.remote.toFixed(2));
    // the loop fades out at the end and back in at the start
    const fade = Math.max(0, Math.min(1, (u - U_START) / FADE, (U_END - u) / FADE));
    layers.all?.setAttribute("opacity", fade.toFixed(2));
    const text = storyOf7(u, t, clockOf(GRAIN, u)) + (paused ? " · paused" : "");
    if (readout && readout.textContent !== text) readout.textContent = text;
  }
  function tick(now) {
    const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
    last = now;
    if (!paused) {
      u += dt / UNIT_SECONDS;
      t += dt;
      if (u >= U_END) { u = U_START; t = 0; }
    }
    render();
    frame = visible && !paused && !still.matches ? requestAnimationFrame(tick) : 0;
  }
  const run = () => { if (!frame && visible && !still.matches) { last = 0; frame = requestAnimationFrame(tick); } };
  const onKey = (e) => { if (e.key === " ") { e.preventDefault(); paused = !paused; if (!paused) run(); else render(); } };
  const observer = new IntersectionObserver((entries) => { visible = entries[entries.length - 1].isIntersecting; if (visible) run(); }, { rootMargin: "120px 0px" });
  observer.observe(stage);
  stage.addEventListener("keydown", onKey);
  // for checks and stills: a moment, paused
  stage.seek = (v, s = 0) => { u = v; t = s; paused = true; render(); };
  // from the start, running: the series page's RESTART button
  stage.restart = () => { u = data.u0 ?? U_START; t = 0; paused = false; render(); run(); };
  render();
  return () => {
    observer.disconnect();
    cancelAnimationFrame(frame);
    stage.removeEventListener("keydown", onKey);
